'use strict';
const $=s=>document.querySelector(s),canvas=$('#farm'),ctx=canvas.getContext('2d');
const KEY='clover-farm-v1',breeds=[['Holstein','#f4f0df','#444c40'],['Jersey','#cc9a61','#80583e'],['Highland','#b27749','#704d36'],['Belted Galloway','#39463d','#f4efdf']];
const ORIGINAL_LAYOUT={barn:{x:-5,y:-6},pond:{x:5.6,y:-5},plots:{x:-4,y:3},trough:{x:5,y:0},hay:{x:-6,y:-.5},farmer:{x:1,y:-.2},lantern:{x:2,y:6},sign:{x:1.5,y:8},trees:[[-7,-5,1.35,4],[1,-7,1.2,9],[7,-1,1.05,14],[-7,2,1.05,19],[-3,7,.85,29],[7,-7,.85,37],[-5,8,.55,41]]};
const freshLayout=()=>({...JSON.parse(JSON.stringify(ORIGINAL_LAYOUT)),hidden:{},extras:[],ground:{}});
function layoutValid(l){return l&&Object.keys(ORIGINAL_LAYOUT).filter(k=>k!=='trees').every(k=>l[k]&&Number.isFinite(l[k].x)&&Number.isFinite(l[k].y)&&Math.abs(l[k].x)<=21&&Math.abs(l[k].y)<=21)&&Array.isArray(l.trees)&&l.trees.length<=60&&l.trees.every(t=>Array.isArray(t)&&t.length===4&&t.every(Number.isFinite)&&Math.abs(t[0])<=21&&Math.abs(t[1])<=21&&t[2]>.3&&t[2]<2)&&(l.hidden===undefined||(l.hidden&&Object.keys(l.hidden).every(k=>Object.hasOwn(ORIGINAL_LAYOUT,k)&&typeof l.hidden[k]==='boolean')))&&(l.extras===undefined||(Array.isArray(l.extras)&&l.extras.length<=60&&l.extras.every(e=>['barn','pond','trough','hay','farmer','lantern','sign'].includes(e.type)&&Number.isFinite(e.x)&&Number.isFinite(e.y)&&Math.abs(e.x)<=21&&Math.abs(e.y)<=21)))&&(l.ground===undefined||(l.ground&&Object.keys(l.ground).length<=1800&&Object.entries(l.ground).every(([k,v])=>/^-?\d{1,2},-?\d{1,2}$/.test(k)&&['grass','water','road','field'].includes(v))));}
function anchorPoint(key,x,y,z=0){const a=state.layout[key],b=ORIGINAL_LAYOUT[key];return proj(x+a.x-b.x,y+a.y-b.y,z);}
function atComponent(key,fn){const a=state.layout[key],b=ORIGINAL_LAYOUT[key],d=proj(a.x-b.x,a.y-b.y);g.save();g.translate(d[0]-350,d[1]-215);fn();g.restore();}
function plotPoint(i){if(Number.isFinite(state.plots[i]?.x))return {x:state.plots[i].x,y:state.plots[i].y};return {x:state.layout.plots.x+(i%3)*1.35,y:state.layout.plots.y+Math.floor(i/3)*1.6};}
function componentRects(l=state.layout){const defs={barn:[-.4,-.4,5,4.8],pond:[-2.6,-3.2,5.2,6.4],plots:[-.35,-.35,4.5,3.6],trough:[-.3,-.3,1.7,2.6],hay:[-.9,-1,2.3,2.3]};const all=[];for(const [key,d] of Object.entries(defs))if(!l.hidden?.[key])all.push({key,x:l[key].x+d[0],y:l[key].y+d[1],w:d[2],h:d[3]});for(const e of l.extras||[]){const d=defs[e.type];if(d)all.push({key:e.type,x:e.x+d[0],y:e.y+d[1],w:d[2],h:d[3]});}state.plots.forEach((p,i)=>{if(i>=6&&plotEnabled(i)){const q=plotPoint(i);all.push({key:'field',x:q.x,y:q.y,w:1.1,h:1.25});}});return all;}
function pointBlocked(x,y){if(componentRects().filter(r=>r.key!=='pond').some(r=>x>r.x-.25&&x<r.x+r.w+.25&&y>r.y-.25&&y<r.y+r.h+.25))return true;return state.layout.trees.some(([tx,ty])=>Math.hypot(tx-x,ty-y)<.9);}
// Layout editing is transactional: autosave keeps the committed farm until Save layout.
let editSession=null,editAction='move',editSelection=null,editAdd='tree',editGround='grass',editHover=null;
const EDIT_NAMES={barn:'Barn',pond:'Pond',tree:'Tree',cow:'Cow',field:'Field plot',trough:'Water trough',hay:'Hay bales',farmer:'Farmer',lantern:'Lantern',sign:'Sign'};
function editorDefaults(l){l.hidden??={};l.extras??=[];l.ground??={};return l;}
function primaryVisible(k){return !state.layout.hidden?.[k];}
function plotEnabled(i){return !state.plots[i].disabled&&(i>=6||primaryVisible('plots'));}
function groundType(x,y){return state.layout.ground?.[Math.floor(x)+','+Math.floor(y)];}
function allPonds(){return [...(primaryVisible('pond')?[state.layout.pond]:[]),...(state.layout.extras||[]).filter(e=>e.type==='pond')];}
function beginEdit(){if(editSession)return;editSession=JSON.parse(JSON.stringify(state));editorDefaults(state.layout);editSelection=null;editAction='move';carried=null;pointer=null;panel='arrange';currentScreen='farm';$('#garden-controls').hidden=true;$('#edit-banner').hidden=true;renderEditorDock();}
function finishEdit(commit){if(!editSession)return;const committed=editSession;if(!commit)state=committed;editSession=null;editSelection=null;editHover=null;$('#edit-banner').hidden=true;$('#editor-dock').hidden=true;currentScreen='farm';$('#side').hidden=true;syncScreen();bakeTerrain();save();render();toast(commit?'Layout saved. Your farm is ready.':'Edits discarded. Previous layout restored.');}
function renderArrange(){renderEditorDock();}
function editorEntries(){const out=[];for(const k of Object.keys(ORIGINAL_LAYOUT).filter(k=>k!=='trees'))if(primaryVisible(k)&&(k!=='plots'||state.plots.slice(0,6).some((p,i)=>plotEnabled(i))))out.push({kind:'primary',key:k});state.layout.trees.forEach((_,i)=>out.push({kind:'tree',i}));state.cows.forEach((_,i)=>out.push({kind:'cow',i}));state.plots.forEach((p,i)=>{if(i>=6&&plotEnabled(i))out.push({kind:'plot',i});});state.layout.extras.forEach((e,i)=>out.push({kind:'extra',i,key:e.type}));return out;}
function editLabel(e){return e.kind==='tree'?'Tree '+(e.i+1):e.kind==='cow'?state.cows[e.i].name:e.kind==='plot'?'Field plot '+(e.i+1):e.kind==='extra'?EDIT_NAMES[e.key]+' '+(e.i+2):e.key==='plots'?'Planting field':EDIT_NAMES[e.key];}
function editPosition(e){if(e.kind==='tree'){const t=state.layout.trees[e.i];return {x:t[0],y:t[1]};}if(e.kind==='cow')return state.cows[e.i];if(e.kind==='plot')return plotPoint(e.i);return e.kind==='extra'?state.layout.extras[e.i]:state.layout[e.key];}
function editFootprint(e,x,y){const k=e.kind==='tree'?'tree':e.kind==='cow'?'cow':e.kind==='plot'?'field':e.key;const spec={barn:[-.4,-.4,5,4.8],pond:[-2.6,-3.2,5.2,6.4],plots:[-.35,-.35,4.5,3.6],trough:[-.3,-.3,1.7,2.6],hay:[-.9,-1,2.3,2.3],tree:[-.55,-.55,1.1,1.1],cow:[-.6,-.6,1.2,1.2],field:[0,0,1.1,1.25],farmer:[-.4,-.4,.8,.8],lantern:[-.3,-.3,.6,.6],sign:[-.5,-.3,1,.6]}[k];return {x:x+spec[0],y:y+spec[1],w:spec[2],h:spec[3]};}
function validEditPlace(e,x,y){const r=editFootprint(e,x,y),corners=[[r.x,r.y],[r.x+r.w,r.y],[r.x,r.y+r.h],[r.x+r.w,r.y+r.h]];if(corners.some(([a,b])=>meadow(a,b)>.95))return false;for(const q of editorEntries()){if(JSON.stringify(q)===JSON.stringify(e))continue;const p=editPosition(q),b=editFootprint(q,p.x,p.y);if(r.x<b.x+b.w+.08&&r.x+r.w+.08>b.x&&r.y<b.y+b.h+.08&&r.y+r.h+.08>b.y)return false;}if(e.key!=='pond'){for(let a=r.x;a<=r.x+r.w;a+=.5)for(let b=r.y;b<=r.y+r.h;b+=.5)if(groundType(a,b)==='water')return false;}return true;}
function moveEdit(e,x,y){if(!validEditPlace(e,x,y)){toast('Choose clear ground inside your farm.');return false;}if(e.kind==='tree'){state.layout.trees[e.i][0]=x;state.layout.trees[e.i][1]=y;}else if(e.kind==='cow')Object.assign(state.cows[e.i],{x,y});else if(e.kind==='plot')Object.assign(state.plots[e.i],{x,y});else Object.assign(e.kind==='extra'?state.layout.extras[e.i]:state.layout[e.key],{x,y});bakeTerrain();editSelection=null;render();return true;}
function removeEdit(e){if(e.kind==='tree')state.layout.trees.splice(e.i,1);else if(e.kind==='cow')state.cows.splice(e.i,1);else if(e.kind==='plot')state.plots[e.i].disabled=true;else if(e.kind==='extra')state.layout.extras.splice(e.i,1);else state.layout.hidden[e.key]=true;editSelection=null;bakeTerrain();render();toast('Component removed from draft.');}
function addEdit(x,y){const k=editAdd;if(k==='tree'&&state.layout.trees.length>=60)return toast('Tree limit reached.');if(!['tree','cow','field'].includes(k)&&state.layout.extras.length>=60)return toast('Component limit reached.');if(editorEntries().length>=100)return toast('This farm has reached its component limit.');if(k==='cow'&&state.cows.length>=8)return toast('There is room for eight cows.');const e={kind:'extra',i:-1,key:k};if(k==='tree')e.kind='tree';if(k==='cow')e.kind='cow';if(k==='field')e.kind='plot';if(!validEditPlace(e,x,y))return toast('Choose a clear spot with enough room.');if(k==='tree')state.layout.trees.push([x,y,1,Math.floor(Math.random()*9999)]);else if(k==='cow')state.cows.push({name:'Meadow '+(state.cows.length+1),breed:state.cows.length%4,food:80,love:50,ready:0,x,y});else if(k==='field'){if(state.plots.length>=200)return toast('Field limit reached.');state.plots.push({planted:0,x,y});}else state.layout.extras.push({type:k,x,y});bakeTerrain();render();toast(EDIT_NAMES[k]+' added to draft.');}
function paintGround(x,y){x=Math.floor(x);y=Math.floor(y);if([[x,y],[x+1,y+1]].some(([a,b])=>meadow(a,b)>.95))return;if(editGround==='water'&&editorEntries().some(e=>{const p=editPosition(e),r=editFootprint(e,p.x,p.y);return x<r.x+r.w&&x+1>r.x&&y<r.y+r.h&&y+1>r.y;}))return toast('Move or remove the component before painting water here.');const key=x+','+y;if(editGround==='natural')delete state.layout.ground[key];else state.layout.ground[key]=editGround;if(editGround==='field'&&!state.plots.some((p,i)=>{const q=plotPoint(i);return plotEnabled(i)&&Math.floor(q.x)===x&&Math.floor(q.y)===y;})){if(state.plots.length>=200)return;state.plots.push({planted:0,x,y});}else if(editGround!=='field'){state.plots.forEach((p,i)=>{const q=plotPoint(i);if(i>=6&&Math.floor(q.x)===x&&Math.floor(q.y)===y)p.disabled=true;});}bakeTerrain();}
function editorHit(p){const entries=editorEntries().map(e=>{const a=editPosition(e),r=editFootprint(e,a.x,a.y);return {e,r,depth:a.x+a.y};}).sort((a,b)=>b.depth-a.depth);const cow=cowAt(p);if(cow)return {kind:'cow',i:cow.i};const w=unproject(p.x,p.y);let found=entries.find(({r})=>w.x>=r.x&&w.x<=r.x+r.w&&w.y>=r.y&&w.y<=r.y+r.h);if(found)return found.e;for(const {e} of entries){const a=editPosition(e),q=proj(a.x,a.y),h=e.key==='barn'?65:e.kind==='tree'?55:25;if(Math.abs(p.x-q[0])<17&&p.y<q[1]&&p.y>q[1]-h)return e;}return null;}
function editorClick(p){const w=unproject(p.x,p.y),x=Math.round(w.x*2)/2,y=Math.round(w.y*2)/2;if(editAction==='ground'){paintGround(w.x,w.y);return;}if(editAction==='add'){addEdit(x,y);return;}if(editSelection&&editAction==='move'){moveEdit(editSelection,x,y);return;}const e=editorHit(p);if(!e)return toast('Click directly on a component to select it.');if(editAction==='remove')removeEdit(e);else{editSelection=e;render();}}
function resetDefaultLayout(){state.layout=editorDefaults(freshLayout());state.plots=Array.from({length:6},(_,i)=>({planted:state.plots[i]?.planted||0}));const spots=[[0,1],[4,0],[2,3],[4,4],[-2,0],[1,5],[-5,1.5],[6,4]];state.cows.forEach((c,i)=>{c.x=spots[i][0];c.y=spots[i][1];});editSelection=null;bakeTerrain();render();toast('Default placement restored in the draft. Save layout to keep it.');}
function drawEditorOverlay(){if(!editSession)return;const b=bounds();for(let x=Math.ceil(b.xmin);x<b.xmax;x++)for(let y=Math.ceil(b.ymin);y<b.ymax;y++){if(meadow(x+.5,y+.5)>.92)continue;const p=[proj(x,y),proj(x+1,y),proj(x+1,y+1),proj(x,y+1)];for(let i=0;i<4;i++)line(p[i],p[(i+1)%4],'#e4ecd31e');}if(editSelection||editAction==='add'||editAction==='ground'){const e=editSelection||{kind:editAction==='ground'?'plot':'extra',key:editAdd},w=editHover||unproject(350,235),x=Math.round(w.x*2)/2,y=Math.round(w.y*2)/2,r=editAction==='ground'?{x:Math.floor(w.x),y:Math.floor(w.y),w:1,h:1}:editFootprint(e,x,y),good=editAction==='ground'||validEditPlace(e,x,y);poly([proj(r.x,r.y),proj(r.x+r.w,r.y),proj(r.x+r.w,r.y+r.h),proj(r.x,r.y+r.h)],good?'#adc97870':'#da8e7970');}}

function sellClover(all=true){const n=all?state.clover:Math.min(1,state.clover);if(!n)return toast('Harvest clover from your planting field first.');state.clover-=n;state.coins+=n*4;log('Sold '+n+' harvested clover for '+n*4+' coins.');toast('Harvest sold. +'+n*4+' coins');save();render();updateGarden();}
function useClover(){if(!state.clover)return;const n=state.clover;state.hay+=n;state.clover=0;toast(n+' clover bundles stored as cow feed.');save();render();updateGarden();}
function harvestMarket(){return '<div class="section-title">YOUR CLOVER HARVEST <span>'+state.clover+' BUNDLES</span></div><p class="note">Sell for 4 coins per bundle, or keep your harvest as cow feed.</p><div class="cow-actions"><button data-harvest="one" '+(!state.clover?'disabled':'')+'>Sell 1 · 4 coins</button><button data-harvest="all" '+(!state.clover?'disabled':'')+'>Sell all · '+state.clover*4+' coins</button><button data-harvest="feed" '+(!state.clover?'disabled':'')+'>Store all as feed</button></div>';}
function bindHarvest(root){root.querySelectorAll('[data-harvest]').forEach(b=>b.onclick=()=>b.dataset.harvest==='feed'?useClover():sellClover(b.dataset.harvest==='all'));}
let currentScreen='farm';
function syncScreen(){document.body.classList.toggle('page-open',currentScreen!=='farm');document.body.classList.toggle('editing',!!editSession);$('#side').hidden=currentScreen==='farm'||currentScreen==='content';$('#modal').hidden=currentScreen!=='content';$('#home').classList.toggle('active',currentScreen==='farm'&&!editSession);document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===currentScreen||b.dataset.panel==='arrange'&&!!editSession));}
function returnToFarm(){if(editSession)return;currentScreen='farm';milking=null;syncScreen();}
function goPage(key){if(editSession){toast('Save or cancel your layout edits before changing screens.');return;}milking=null;if(key==='land')key='shop';if(key==='journal'){help('notes');return;}if(key==='arrange'){beginEdit();return;}currentScreen=key;panel=key;render();syncScreen();}
function openScreen(html,title){if(editSession){toast('Save or cancel your layout edits before changing screens.');return false;}if(!html.includes('id="stop-milk"'))milking=null;currentScreen='content';$('#modal-body').innerHTML='<div class="screen-heading"><button class="back-farm" id="content-back">← Back to farm</button><span>CLOVER · '+esc(title||(html.match(/<h2>([^<]+)<\/h2>/)||[])[1]||'Farm')+'</span></div><div class="screen-content">'+html+'</div>';$('#content-back').onclick=returnToFarm;syncScreen();return true;}
function closeContentScreen(){returnToFarm();}
function renderEditorDock(){const dock=$('#editor-dock');dock.hidden=false;$('#side').hidden=true;$('#edit-banner').hidden=true;currentScreen='farm';syncScreen();dock.innerHTML='<div class="edit-dock-main"><span class="edit-mode-label">✎ EDIT MODE</span><div class="editor-tabs">'+['move','add','remove','ground'].map(a=>'<button data-edit-action="'+a+'" class="'+(a===editAction?'selected':'')+'">'+({move:'↔ Move',add:'+ Add',remove:'− Remove',ground:'▧ Ground'}[a])+'</button>').join('')+'</div><div class="edit-save-actions"><button class="editor-secondary" id="editor-reset">Reset to default</button><button class="editor-secondary" id="editor-cancel">Cancel</button><button class="primary" id="editor-save">Save layout</button></div></div>'+(editAction==='add'?'<div class="edit-choices" aria-label="Components">'+Object.entries(EDIT_NAMES).map(([k,v])=>'<button data-add-type="'+k+'" class="'+(k===editAdd?'selected':'')+'">'+v+'</button>').join('')+'</div>':'')+(editAction==='ground'?'<div class="edit-choices" aria-label="Ground types">'+['grass','water','road','field','natural'].map(k=>'<button data-ground-type="'+k+'" class="'+(k===editGround?'selected':'')+'">'+k[0].toUpperCase()+k.slice(1)+'</button>').join('')+'</div>':'')+'<p class="edit-dock-hint">'+(editSelection?'Selected: '+esc(editLabel(editSelection))+'. Click clear ground to place.':{move:'Click any component to pick it up, then click a new spot. Escape clears selection.',add:'Choose a component above, then click open ground to place it.',remove:'Click a component on the farm to remove it from the draft.',ground:'Choose a ground type above, then click tiles on the farm to paint.'}[editAction])+'</p>';
dock.querySelectorAll('[data-edit-action]').forEach(b=>b.onclick=()=>{editAction=b.dataset.editAction;editSelection=null;renderEditorDock();});dock.querySelectorAll('[data-add-type]').forEach(b=>b.onclick=()=>{editAdd=b.dataset.addType;renderEditorDock();});dock.querySelectorAll('[data-ground-type]').forEach(b=>b.onclick=()=>{editGround=b.dataset.groundType;renderEditorDock();});$('#editor-save').onclick=()=>finishEdit(true);$('#editor-cancel').onclick=()=>finishEdit(false);$('#editor-reset').onclick=resetDefaultLayout;}
function showGuideText(){openScreen('<div class="eyebrow">THE CLOVER USER GUIDE</div><h2>A farm at your pace.</h2><p class="screen-lead">Everything you need to care for your herd and make the meadow your own.</p><div class="guide-grid"><article><h3>01 · Care for your cows</h3><p>Choose Pet (1), Feed (2), or Milk (3), then click a cow. Feed uses one hay bundle and restores fullness. Petting raises affection. Herd has the same care controls.</p></article><article><h3>02 · Milk & earn coins</h3><p>Milking opens its own game screen. Stop the marker in the green zone for extra bottles. Cows rest for 45 seconds afterward and need at least 25% fullness. Sell milk for 18 coins per bottle or deliver six bottles to the café for 150 coins.</p></article><article><h3>03 · Plant & harvest</h3><p>Choose Grow (4). Click a field plot to plant free clover. After 30 seconds, harvest four bundles. Sell them for 4 coins each or store them as hay. Painted fields in Edit mode work as planting plots too.</p></article><article><h3>04 · Move the herd</h3><p>Drag a cow across the farm, or choose Move (5), click a cow, then click its destination. Green means a clear spot; red means blocked. Selected cows can also move with arrow keys and be placed with Enter.</p></article><article><h3>05 · Design your farm</h3><p>Choose Design farm on the Farm screen. Move, Add, Remove, and Ground replace the bottom tools. Select components directly on the farm. Add uses component buttons; Ground uses grass, water, road, field, or natural buttons. New placements must fit inside the farm and avoid other objects.</p></article><article><h3>06 · Save, cancel & reset</h3><p>Edit changes remain a draft until Save layout. Cancel restores your previous farm. Reset to default restores the original placement and ground in the draft; save to keep it. Coins, supplies, and your herd stay with you.</p></article><article><h3>07 · Grow the pasture</h3><p>The Farm shop pasture cards add a connected strip of land to an edge. The first costs 150 coins, with each later expansion costing 100 more. Each edge expands twice. The camera fits the enlarged farm automatically.</p></article><article><h3>08 · Seasons & skies</h3><p>Click the weather display to open the Climate screen. Pick Spring, Summer, Autumn, or Winter and a sky condition. Seasons advance every seven farm days. Thunderstorms, blizzards, heatwaves, and gales change the atmosphere.</p></article><article><h3>09 · Camera & sound</h3><p>Drag empty ground to pan the farm. Scroll over it to zoom, or use − / + (Z / X). N switches day and night. P pauses ambient motion. The sound button enables short action sounds. Lighting and shadows change gradually with the time. Barn lights and lanterns fade on toward dusk. Cows take a short stroll roughly every minute; unfrozen ponds occasionally have jumping fish.</p></article><article><h3>10 · Keep your progress</h3><p>Your farm saves in this browser. Settings & backups below lets you download a backup or load one on another device. Draft edits are not committed by autosave. Return to Farm from any game screen to resume playing.</p></article></div>','User guide');}

function renderShop(side){const price=180+Math.max(0,state.cows.length-2)*100,landCost=landPrice(),b=bounds();const tile=(title,body,action)=>'<article class="shop-tile"><h3>'+title+'</h3><p>'+body+'</p><div class="tile-actions">'+action+'</div></article>';const buyButton=(kind,label,disabled)=>'<button class="primary" data-buy="'+kind+'" '+(disabled?'disabled':'')+'>'+label+'</button>';
side.innerHTML='<div class="shop-title"><div><div class="eyebrow">FARM SHOP · ROOM TO ROAM</div><h2>Everything for your meadow.</h2><p class="note">'+state.coins+' coins · '+(b.xmax-b.xmin)+' × '+(b.ymax-b.ymin)+' tiles of pasture</p></div></div><div class="shop-grid">'+tile('♧ Fresh hay','Ten bundles to keep your cows full.',buyButton('hay','Buy · 25 coins',state.coins<25))+tile('♡ A new companion','Welcome a '+breeds[state.cows.length%4][0]+'. '+state.cows.length+' / 8 cows.',buyButton('cow',state.cows.length>=8?'Herd is full':'Adopt · '+price+' coins',state.coins<price||state.cows.length>=8))+tile('♙ Better dairy pail','Level '+state.upgrade+' / 5. Adds one bottle per milking.',buyButton('upgrade',state.upgrade>=5?'Fully upgraded':'Upgrade · '+120*(state.upgrade+1)+' coins',state.coins<120*(state.upgrade+1)||state.upgrade>=5))+['north','east','south','west'].map((d,i)=>tile(['↗','↘','↙','↖'][i]+' '+d[0].toUpperCase()+d.slice(1)+' pasture','Add six tiles of connected land. '+state.land[d]+' / 2 expansions.','<button class="primary" data-expand="'+d+'" '+(state.land[d]>=2||state.coins<landCost?'disabled':'')+'>'+(state.land[d]>=2?'Fully expanded':'Add land · '+landCost+' coins')+'</button>')).join('')+tile('♙ Milk market',state.milk+' bottles in the barn. 18 coins per bottle.','<button class="primary" id="sell" '+(!state.milk?'disabled':'')+'>Sell all · '+state.milk*18+' coins</button>')+tile('⚘ Clover harvest',state.clover+' bundles ready. Sell or store them as feed.','<button class="primary" data-harvest="all" '+(!state.clover?'disabled':'')+'>Sell all · '+state.clover*4+' coins</button><button class="editor-secondary" data-harvest="feed" '+(!state.clover?'disabled':'')+'>Store as feed</button>')+'</div>';
side.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>buy(el.dataset.buy));side.querySelectorAll('[data-expand]').forEach(el=>el.onclick=()=>expandLand(el.dataset.expand));$('#sell').onclick=sell;bindHarvest(side);}
function guideExtras(){return '<section id="guide-settings" class="guide-section"><div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>Your farm settings.</h2><p>Your progress saves in this browser. Download a backup to keep it or move to another device.</p><div class="guide-setting-actions"><button class="primary" id="export">Download save</button><button class="editor-secondary" id="import">Load a backup</button><button class="editor-secondary" id="sound">Sound effects: '+(audio?'on':'off')+'</button></div><input type="file" id="load" accept="application/json,.json" hidden><div id="load-confirm" class="load-confirm"></div></section><section id="guide-notes" class="guide-section"><div class="eyebrow">NOTES FROM THE MEADOW</div><h2>The small things.</h2><div class="milestone">'+state.sold+' bottles shared · '+state.harvested+' clover harvests · '+state.pets+' moments of love<p>'+new Set(state.cows.map(c=>c.breed)).size+' / 4 breeds welcomed</p></div>'+state.log.map(t=>'<div class="journal-entry">'+esc(t)+'</div>').join('')+'</section>';}
function bindGuideSettings(){$('#sound').onclick=()=>{audio=!audio;$('#sound').textContent='Sound effects: '+(audio?'on':'off');$('#ambience').setAttribute('aria-pressed',String(audio));$('#ambience').innerHTML='♪ <span>Sound '+(audio?'on':'off')+'</span>';sound();};$('#export').onclick=()=>{save();const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='clover-farm-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import').onclick=()=>$('#load').click();$('#load').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>100000)throw Error();const s=JSON.parse(await f.text());if(!valid(s))throw Error();$('#load-confirm').innerHTML='<p>Backup: '+s.cows.length+' cows · '+s.coins+' coins. Loading replaces your current farm.</p><button class="primary" id="confirm-load">Load this backup</button>';$('#confirm-load').onclick=()=>{state=migrate(s);bakeTerrain();save();help('settings');toast('Backup loaded.');};}catch{toast('That file is not a valid Clover backup.');}};}
function help(section='guide'){if(editSession)return toast('Save or cancel edits before opening the guide.');showGuideText();$('#modal-body .screen-content').insertAdjacentHTML('afterbegin','<div class="guide-jumps"><button data-guide-jump="guide">User guide</button><button data-guide-jump="settings">Settings & backups</button><button data-guide-jump="notes">Meadow notes</button></div><div id="guide-top"></div>');$('#modal-body .screen-content').insertAdjacentHTML('beforeend',guideExtras());bindGuideSettings();document.querySelectorAll('[data-guide-jump]').forEach(el=>el.onclick=()=>{const id=el.dataset.guideJump==='guide'?'guide-top':'guide-'+el.dataset.guideJump;$('#'+id).scrollIntoView({behavior:'smooth',block:'start'});});if(section==='settings'||section==='notes')$('#guide-'+section).scrollIntoView({block:'start'});}
