const SEASONS=['Spring','Summer','Autumn','Winter'],WEATHERS=['☀ Sunny','☁ Overcast','☂ Rain','ϟ Thunderstorm','❄ Blizzard','♨ Heatwave','≋ Gale'];
let carried=null,pointer=null,pan={x:0,y:0};
function camera(){const b=bounds(),p=proj((b.xmin+b.xmax)/2,(b.ymin+b.ymax)/2),width=((b.xmax-b.xmin)+(b.ymax-b.ymin))*17,height=width/2+65;return {x:p[0]-pan.x,y:p[1]-8-pan.y,scale:zoom*Math.min(1,625/width,390/height)};}
function setZoom(value){zoom=Math.max(.5,Math.min(2.8,value));}
function screenPoint(e){const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/700,r.height/470),cam=camera();let x=(e.clientX-r.left-(r.width-700*scale)/2)/scale,y=(e.clientY-r.top-(r.height-470*scale)/2)/scale;return {x:(x-350)/cam.scale+cam.x,y:(y-235)/cam.scale+cam.y};}
function unproject(x,y){let a=(x-350)/17,b=(y-215)/8.5;return {x:(a+b)/2,y:(b-a)/2};}
function cowAt(p){return hitCows.slice().reverse().find(c=>Math.abs(p.x-c.x)<25&&Math.abs(p.y-c.y)<23);}
function validDrop(x,y,i){const b=bounds();if(x<b.xmin+.7||x>b.xmax-.7||y<b.ymin+.7||y>b.ymax-.7||meadow(x,y)>.92||pond(x,y)<1.2||pointBlocked(x,y))return false;return !state.cows.some((c,j)=>j!==i&&Math.hypot(c.x-x,c.y-y)<1.15);}
function pickCow(i){returnToFarm();const c=state.cows[i];carried={i,x:c.x,y:c.y};$('#side').hidden=true;chooseTool('move');canvas.style.cursor='grabbing';toast('Move '+c.name+' to a free spot. Click to place; Escape cancels.');}
function dropCow(){if(!carried)return;const {i,x,y}=carried,c=state.cows[i];if(validDrop(x,y,i)){c.x=Math.round(x*4)/4;c.y=Math.round(y*4)/4;log('Moved '+c.name+' to a new patch of pasture.');toast(c.name+' has a lovely new spot.');save();render();}else toast('Choose open pasture, away from water, buildings, crops, and other cows.');carried=null;canvas.style.cursor='grab';}
function tapFarm(p){let cow=cowAt(p);if(tool==='move'){if(carried){const w=unproject(p.x,p.y);carried.x=w.x;carried.y=w.y;dropCow();}else if(cow)pickCow(cow.i);else toast('Select a cow first, then click open pasture.');return;}if(cow&&tool!=='grow'){({pet,feed,milk}[tool])(cow.i);return;}const plot=hitPlots.find(q=>Math.abs(p.x-q.x)<22&&Math.abs(p.y-q.y)<13);if(plot){grow(plot.i);return;}toast('Drag a cow to move it, or choose a farm tool.');}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=screenPoint(e);if(editSession){editorClick(p);return;}const c=cowAt(p),onComponent=!!editorHit(p);pointer={id:e.pointerId,startX:e.clientX,startY:e.clientY,cow:c?.i,moved:false,panning:!onComponent&&!carried,panX:pan.x,panY:pan.y};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{const p=screenPoint(e);if(editSession){editHover=unproject(p.x,p.y);return;}if(pointer&&pointer.id===e.pointerId&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>5){if(pointer.panning){const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/700,r.height/470)*camera().scale;pan.x=Math.max(-450,Math.min(450,pointer.panX+(e.clientX-pointer.startX)/scale));pan.y=Math.max(-300,Math.min(300,pointer.panY+(e.clientY-pointer.startY)/scale));pointer.moved=true;canvas.style.cursor='grabbing';return;}if(pointer.cow!==undefined){if(!pointer.moved){pickCow(pointer.cow);pointer.moved=true;}const w=unproject(p.x,p.y+12);carried.x=w.x;carried.y=w.y;}}else if(carried&&!pointer){const w=unproject(p.x,p.y);carried.x=w.x;carried.y=w.y;}else if(!pointer)canvas.style.cursor=cowAt(p)?'grab':'default';});
canvas.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const {moved,panning}=pointer;pointer=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);canvas.style.cursor='default';if(moved&&panning)return;if(moved)dropCow();else tapFarm(screenPoint(e));});
canvas.addEventListener('pointercancel',()=>{pointer=null;carried=null;canvas.style.cursor='default';});
canvas.addEventListener('wheel',e=>{e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?300:1);setZoom(zoom*Math.exp(-Math.max(-180,Math.min(180,delta))*.0015));},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='Escape'){carried=null;pointer=null;canvas.style.cursor='default';}if(carried&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter')dropCow();else{const moves={ArrowLeft:[-.5,.5],ArrowRight:[.5,-.5],ArrowUp:[-.5,-.5],ArrowDown:[.5,.5]},d=moves[e.key];carried.x+=d[0];carried.y+=d[1];}}});
function drawCarried(time){if(!carried)return;const p=proj(carried.x,carried.y),good=validDrop(carried.x,carried.y,carried.i);ellipse(p[0],p[1],19,7,good?'#a8cc7c88':'#d18c7c99');drawCow(g,p[0],p[1]-30,1.35,state.cows[carried.i].breed,1,time);g.font='9px monospace';g.textAlign='center';g.fillStyle=good?'#edf3da':'#f6d2c5';g.fillText(good?'Place here':'Blocked',p[0],p[1]-49);}
function landPrice(){return 150+Object.values(state.land).reduce((a,b)=>a+b,0)*100;}
function expandLand(direction){if(!['north','east','south','west'].includes(direction)||state.land[direction]>=2||state.coins<landPrice())return false;const price=landPrice();state.coins-=price;state.land[direction]++;zoom=1;pan={x:0,y:0};bakeTerrain();log('Expanded the '+direction+' pasture for '+price+' coins.');toast('New pasture added. Drag your cows onto the new land.');save();render();return true;}
function renderLand(side){const price=landPrice(),b=bounds();side.innerHTML='<div class="eyebrow">ROOM TO ROAM</div><h2>Grow your meadow.</h2><p class="note">Add a connected strip of isometric land, six tiles deep. New ground becomes usable pasture immediately.</p><div class="milestone">'+(b.xmax-b.xmin)+' × '+(b.ymax-b.ymin)+' tiles of pasture<p>Each edge can expand twice.</p></div>'+['north','east','south','west'].map((d,i)=>'<div class="shop-item"><b>'+['↗','↘','↙','↖'][i]+' '+d[0].toUpperCase()+d.slice(1)+' pasture</b><p>'+state.land[d]+' / 2 expansions</p><button class="primary" data-expand="'+d+'" '+(state.land[d]>=2||state.coins<price?'disabled':'')+'>'+(state.land[d]>=2?'Fully expanded':'Add land · '+price+' coins')+'</button></div>').join('');side.querySelectorAll('[data-expand]').forEach(b=>b.onclick=()=>expandLand(b.dataset.expand));}
function openClimate(){if(editSession)return toast('Save or cancel layout edits before changing climate.');openScreen('<div class="eyebrow">THE WORLD AROUND YOU</div><h2>Seasons & skies.</h2><p class="note">Choose your atmosphere. Seasons also advance every seven farm days. Weather stays as you choose it.</p><label class="climate-label">Season<select id="season-choice">'+SEASONS.map((x,i)=>'<option value="'+i+'" '+(i===state.season?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label class="climate-label">Weather<select id="weather-choice">'+WEATHERS.map((x,i)=>'<option value="'+i+'" '+(i===state.weather?'selected':'')+'>'+x+'</option>').join('')+'</select></label><p class="note">Thunderstorms bring wind and occasional lightning. Blizzards bring driving snow; gales carry leaves. Use Pause to still the atmosphere.</p><button class="primary wide" id="apply-climate">Apply season & weather</button>');$('#apply-climate').onclick=()=>{state.season=+$('#season-choice').value;state.weather=+$('#weather-choice').value;bakeTerrain();save();render();closeContentScreen();toast(SEASONS[state.season]+' · '+WEATHERS[state.weather]);};}
function glow(x,y,rx,ry,color,alpha){g.save();g.translate(x,y);g.scale(1,ry/rx);const grad=g.createRadialGradient(0,0,0,0,0,rx);grad.addColorStop(0,'rgba('+color+','+alpha+')');grad.addColorStop(.4,'rgba('+color+','+alpha*.45+')');grad.addColorStop(1,'rgba('+color+',0)');g.fillStyle=grad;g.fillRect(-rx,-rx,rx*2,rx*2);g.restore();}
function barnFixtures(x,y){
// Two side windows sit in the right wall's isometric plane.
for(const yy of [y+.9,y+2.4]){poly([proj(x+4.23,yy,1.1),proj(x+4.23,yy+.8,1.1),proj(x+4.23,yy+.8,1.9),proj(x+4.23,yy,1.9)],'#d1b78b');poly([proj(x+4.25,yy+.12,1.23),proj(x+4.25,yy+.68,1.23),proj(x+4.25,yy+.68,1.77),proj(x+4.25,yy+.12,1.77)],mixLight('#51685c','#ebbb68',ambientLight.night));line(proj(x+4.26,yy+.4,1.2),proj(x+4.26,yy+.4,1.8),'#8e7957',1);line(proj(x+4.26,yy+.1,1.5),proj(x+4.26,yy+.7,1.5),'#8e7957',1);}
for(const xx of [x+1,x+3.3]){const p=proj(xx,y+3.9,2.1);g.fillStyle='#493e2e';g.fillRect(p[0]-2,p[1]-3,4,7);g.fillStyle=mixLight('#b9a174','#ffda89',ambientLight.night);g.fillRect(p[0]-1,p[1]-1,2,3);}
}
function nightLightsBase(time){const b=state.layout.barn,flicker=1+Math.sin(time*2.1)*.025,window=proj(b.x+2.1,b.y+3.85,3.15),door=proj(b.x+2.1,b.y+4.1),post=anchorPoint('lantern',2,6,1.75),postGround=anchorPoint('lantern',2,6);g.save();g.globalCompositeOperation='screen';glow(window[0],window[1],27,25,'255,191,86',.62);glow(door[0]+3,door[1]+10,76,33,'255,187,78',.62);glow(door[0],door[1]-26,36,40,'255,178,67',.28);glow(postGround[0],postGround[1],47,20,'255,185,75',.38);glow(post[0],post[1],22,26,'255,183,70',.45);
for(const xx of [b.x+1,b.x+3.3]){const p=proj(xx,b.y+3.9,2.1);glow(p[0],p[1],31,36,'255,184,73',.6*flicker);const q=proj(xx,b.y+4.2);glow(q[0]+5,q[1]+5,40,20,'255,194,88',.3);}
for(const yy of [b.y+.9,b.y+2.4]){const p=proj(b.x+4.26,yy+.4,1.5),q=proj(b.x+5,yy+.4);glow(p[0],p[1],27,25,'255,188,83',.5);glow(q[0],q[1]+4,38,17,'255,190,86',.3);}g.restore();
// Repaint warm light sources after grading, preserving the window crossbars.
g.fillStyle='#ffe4a0';g.fillRect(window[0]-3,window[1]-3,6,6);line([window[0],window[1]-3],[window[0],window[1]+3],'#b69458');line([window[0]-3,window[1]],[window[0]+3,window[1]],'#b69458');for(const xx of [b.x+1,b.x+3.3]){const p=proj(xx,b.y+3.9,2.1);g.fillStyle='#fff0b9';g.fillRect(p[0]-1,p[1]-1,2,3);}for(const yy of [b.y+.9,b.y+2.4]){poly([proj(b.x+4.25,yy+.12,1.23),proj(b.x+4.25,yy+.68,1.23),proj(b.x+4.25,yy+.68,1.77),proj(b.x+4.25,yy+.12,1.77)],'#ffd78b');line(proj(b.x+4.26,yy+.4,1.2),proj(b.x+4.26,yy+.4,1.8),'#b28b50',1);line(proj(b.x+4.26,yy+.1,1.5),proj(b.x+4.26,yy+.7,1.5),'#b28b50',1);}g.fillStyle='#fff0b5';g.fillRect(post[0]-2,post[1]-2,4,5);
// Warm threshold and a narrow seam of light under the barn doors.
line(proj(b.x+1.28,b.y+3.87,.06),proj(b.x+2.94,b.y+3.87,.06),'#f4cf86',1);line(proj(b.x+2.1,b.y+3.87,.05),proj(b.x+2.1,b.y+3.87,2.08),'#c59b593c',1);
}
function drawExtremeWeather(time){const w=state.weather,snow=w===4||(state.season===3&&w<3),rain=w===2||w===3;g.save();if(w===3){g.globalCompositeOperation='source-atop';g.fillStyle='#14243733';g.fillRect(-550,-265,1800,1000);g.restore();g.save();}
if(rain)for(let j=0;j<(w===3?190:75);j++){const x=(hash(j,91)*1200-time*(w===3?65:18)+2400)%1200-250,y=(hash(j,92)*720+time*(w===3?240:120))%720-120;line([x,y],[x-(w===3?7:2),y+10],w===3?'#acc4d078':'#9ab6ba65');}
if(snow)for(let j=0;j<(w===4?200:55);j++){const x=(hash(j,81)*1200-time*(w===4?45:5)+2400)%1200-250,y=(hash(j,82)*720+time*(w===4?75:18))%720-120;g.fillStyle=j%3?'#f0f6e4b0':'#a9c4c188';g.fillRect(Math.round(x+Math.sin(time+j)*3),Math.round(y),w===4?2:1,1);}
if(w===6)for(let j=0;j<60;j++){const x=(hash(j,61)*1100+time*90)%1100-200,y=80+hash(j,62)*360+Math.sin(time*2+j)*18;line([x,y],[x+3,y+1],j%2?'#bb945b99':'#d2b87899');}
if(w===5){g.globalCompositeOperation='source-atop';g.fillStyle='#f6ac3422';g.fillRect(-550,-265,1800,1000);for(let j=0;j<12;j++)line([200+j*25,200+Math.sin(time+j)*12],[205+j*25,180+Math.sin(time+j)*12],'#efd99a22');}
if(w===3&&!motionPaused&&time%14>12.4&&time%14<12.55){g.globalCompositeOperation='source-atop';g.fillStyle='#c9dbf05a';g.fillRect(-550,-265,1800,1000);g.globalCompositeOperation='source-over';let p=proj(7,-7,6);poly([[p[0],p[1]],[p[0]-10,p[1]+29],[p[0]-2,p[1]+26],[p[0]-15,p[1]+55],[p[0]+2,p[1]+20],[p[0]-5,p[1]+22]],'#d8e7edb0');}g.restore();}
let lastSim=Date.now();setInterval(()=>{if(editSession)return;let dt=Math.min((Date.now()-lastSim)/1000,5);lastSim=Date.now();state.minute+=dt*2;if(state.minute>=1440){state.minute-=1440;state.day++;if((state.day-1)%7===0){state.season=(state.season+1)%4;bakeTerrain();toast(SEASONS[state.season]+' has arrived.');}log('A new day in the meadow.');}state.night=state.minute<360||state.minute>=1140;state.cows.forEach(c=>c.food=Math.max(0,c.food-dt*.025));const h=Math.floor(state.minute/60),m=Math.floor(state.minute%60);$('#clock').textContent=(h%12||12)+':'+String(m).padStart(2,'0')+(h>=12?' PM':' AM');$('#day').textContent='DAY '+state.day+' · '+SEASONS[state.season].toUpperCase();$('#weather').textContent=WEATHERS[state.weather];$('#clock-hand').style.transform='rotate('+(state.minute/1440*360-180)+'deg)';$('#period').textContent=' · '+(h<6?'Night':h<12?'Morning':h<17?'Afternoon':h<20?'Evening':'Night');updateGarden();document.querySelectorAll('[data-ready]').forEach(e=>{const c=state.cows[+e.dataset.ready];e.textContent=c.ready>Date.now()?'Resting · '+Math.ceil((c.ready-Date.now())/1000)+'s':'Milk is ready';});},1000);
setInterval(save,15000);window.addEventListener('pagehide',save);render();requestAnimationFrame(draw);

$('#pause-motion').setAttribute('aria-pressed',String(motionPaused));$('#pause-motion').onclick=()=>{motionPaused=!motionPaused;$('#pause-motion').setAttribute('aria-pressed',String(motionPaused));$('#pause-motion').setAttribute('aria-label',motionPaused?'Resume ambient animation':'Pause ambient animation');$('#pause-motion').innerHTML=(motionPaused?'▷':'Ⅱ')+'<kbd>P</kbd>';};$('#ambience').onclick=()=>{audio=!audio;$('#ambience').setAttribute('aria-pressed',String(audio));$('#ambience').innerHTML='♪ <span>Sound '+(audio?'on':'off')+'</span>';sound();};$('#credits').onclick=()=>openScreen('<div class="eyebrow">A LITTLE COW FARM</div><h2>Clover Meadow</h2><p>An original pixel-art cow farming game inspired by the peaceful world of <a href="https://github.com/nxtr1609/lakeside" target="_blank" rel="noopener">Lakeside by nxtr1609</a>.</p><p class="note">Procedural terrain, foliage, lighting, cow sprites, and sound effects made for Clover. Your progress stays in this browser.</p>');

function findCowSpot(){const b=bounds();for(let n=0;n<600;n++){const x=b.xmin+1+Math.random()*(b.xmax-b.xmin-2),y=b.ymin+1+Math.random()*(b.ymax-b.ymin-2);if(validDrop(x,y,-1))return {x,y};}return null;}

function drawFarmSign(){let sign=anchorPoint('sign',1.5,8,.1);line([sign[0],sign[1]],[sign[0],sign[1]-23],'#7f7250',3);g.fillStyle='#d9cca3';g.fillRect(sign[0]-17,sign[1]-25,34,12);line([sign[0]-17,sign[1]-25],[sign[0]+17,sign[1]-25],'#eee0ba');g.fillStyle='#5c694a';g.font='7px monospace';g.textAlign='center';g.fillText('CLOVER',sign[0],sign[1]-17);
}

function nightLights(time){const barn=state.layout.barn,lantern=state.layout.lantern;try{if(!primaryVisible('barn'))state.layout.barn={x:1000,y:1000};if(!primaryVisible('lantern'))state.layout.lantern={x:1000,y:1000};nightLightsBase(time);for(const e of state.layout.extras){if(e.type==='barn'){state.layout.barn=e;state.layout.lantern={x:1000,y:1000};nightLightsBase(time);}if(e.type==='lantern'){state.layout.barn={x:1000,y:1000};state.layout.lantern=e;nightLightsBase(time);}}}finally{state.layout.barn=barn;state.layout.lantern=lantern;}}

